// Node test for assets/js/stats-display.js (Python supercharge, slice 3).
// Renders a stats.json (pre-computed by tools/stats.py) through the pure
// PSStats.render() and asserts the HTML carries the pre-computed numbers.
// Expectations are derived from the stats file itself, so the test stays
// valid as the data moves — it proves the display shows the pre-computed
// numbers, whatever they are. No network, no browser.
//
//   node tests/test_stats_display.js [path/to/stats.json]
// Default stats path: /tmp/stats.json (generated by tools/stats.py).
// The Python suite (tests/test_stats.py) runs this automatically with
// the stats.json it generates.
const fs = require('fs');
const statsPath = process.argv[2] || '/tmp/stats.json';
const stats = JSON.parse(fs.readFileSync(statsPath, 'utf8'));
// minimal browser stubs: the loader must not fire (no #pvStats element)
global.window = {};
global.document = {readyState: 'complete', getElementById: () => null,
  addEventListener: () => {}};
global.fetch = () => Promise.reject(new Error('no network in test'));
eval(fs.readFileSync(__dirname + '/../assets/js/stats-display.js', 'utf8'));
const html = window.PSStats.render(stats);
let fail = 0;
function check(name, cond, detail) {
  if (!cond) { fail++; console.log('FAIL ' + name + (detail ? ' — ' + detail : '')); }
  else console.log('PASS ' + name);
}
function pc(x) { return (x >= 0 ? '+' : '') + x.toFixed(2) + '%'; }
function usd(x) {
  return (x < 0 ? '-$' : '$') + Math.abs(x).toLocaleString('en-US', {maximumFractionDigits: 0});
}
check('renders something', html.length > 500, html.length);
// every series' headline numbers appear, formatted as the render does
for (const [k, s] of Object.entries(stats.series)) {
  check('series ' + k + ' YTD ' + pc(s.ytd_pct), html.includes(pc(s.ytd_pct)), s.ytd_pct);
  check('series ' + k + ' drawdown ' + pc(s.drawdown_pct), html.includes(pc(s.drawdown_pct)), s.drawdown_pct);
  check('series ' + k + ' vol ' + pc(s.vol_ann_pct), html.includes(pc(s.vol_ann_pct)), s.vol_ann_pct);
  if (s.best_day) check('series ' + k + ' best day', html.includes(pc(s.best_day.pct)), s.best_day);
  if (s.worst_day) check('series ' + k + ' worst day', html.includes(pc(s.worst_day.pct)), s.worst_day);
}
// monthly returns (sleeves) appear
for (const mo of Object.keys(stats.series.berkshire.monthly)) {
  check('monthly ' + mo + ' berkshire', html.includes(pc(stats.series.berkshire.monthly[mo])), mo);
}
check('MTD marker *', html.includes(' *') && html.includes('month-to-date'), 'mtd');
// Pulse lines carry the pre-computed $ values
for (const [k, p] of Object.entries(stats.pulse)) {
  check('pulse ' + k + ' value ' + usd(p.value), html.includes(usd(p.value)), p.value);
  check('pulse ' + k + ' below peak ' + usd(p.below_peak), html.includes(usd(p.below_peak)), p.below_peak);
}
// badges, dividends, CSV
for (const b of stats.badges) {
  check('badge: ' + b.text, html.includes(b.text), b.text);
}
if (stats.dividends.upcoming.length) {
  const nx = stats.dividends.upcoming[0];
  const M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const payFmt = M[+nx.pay.slice(5, 7) - 1] + ' ' + (+nx.pay.slice(8, 10));
  check('dividend: next payment ' + payFmt, html.includes(payFmt), nx.pay);
  check('dividend: per-share', html.includes('$' + (+nx.per_share).toFixed(4)), nx.per_share);
  check('dividend: Berkshire cash', html.includes('$' + nx.cash.berkshire.toFixed(2)), nx.cash.berkshire);
  check('dividend: upcoming count', html.includes(String(stats.dividends.upcoming.length) + ' daily payments left'), 'count');
  const mo = nx.record.slice(0, 7);
  if (stats.dividends.month_totals[mo]) {
    check('dividend: month total', html.includes('$' + stats.dividends.month_totals[mo].per_share.toFixed(2) + '/share declared'), 'month');
  }
}
check('CSV link', html.includes('history.csv') && html.includes('Download the full history as CSV'), 'csv');
check('no undefined/null leaked', !html.includes('undefined') && !html.includes('null'), 'leak');
// empty / missing stats renders nothing (section stays hidden)
check('empty stats renders empty', window.PSStats.render(null) === '' && window.PSStats.render({}) === '');
console.log(fail === 0 ? '\nDISPLAY: all checks pass' : '\nDISPLAY: ' + fail + ' FAILED');
process.exit(fail ? 1 : 0);
